from abc import ABC, abstractmethod


class TsesAuthenticationInterface(ABC):
    """Contract for authentication providers used by the scaffold.

    This interface is intentionally narrow. Projects can subclass it for OTP,
    passwordless, social, or vendor-backed authentication flows without changing
    the higher-level calling code.
    """

    @abstractmethod
    def signup(self):
        """Create a new authentication subject or begin a signup flow."""

    @abstractmethod
    def verify_otp(self):
        """Validate a one-time password or equivalent verification token."""

    @abstractmethod
    def generate_access_token(self):
        """Issue an access token after a successful authentication flow."""

    @abstractmethod
    def resend_otp(self):
        """Re-issue a verification code or temporary access token."""

    @abstractmethod
    def reset_password(self):
        """Reset a user password.

        Override this when the authentication provider supports password-based
        flows. Providers that do not expose password resets should still
        implement the method and raise a domain-specific exception explicitly.
        """
